const input = $input.first().json;
const payload = input.body ?? input;
const startedAtMs = Date.now();
const errors = [];
const knownPrisms = new Set([
  'plasticidade_humana',
  'empreendedorismo',
  'multiculturalismo',
  'neuroinovacao',
  'tomada_decisao',
]);

if (payload.contract_version !== 'beta-1') {
  errors.push('contract_version deve ser beta-1');
}
if (typeof payload.request_id !== 'string' || payload.request_id.trim() === '') {
  errors.push('request_id e obrigatorio');
}
if (typeof payload.form_response_id !== 'string' || payload.form_response_id.trim() === '') {
  errors.push('form_response_id e obrigatorio');
}
if (!Array.isArray(payload.answers) || payload.answers.length === 0) {
  errors.push('answers deve ser uma lista nao vazia');
}

const answers = Array.isArray(payload.answers) ? payload.answers : [];
for (const [index, answer] of answers.entries()) {
  if (typeof answer.question_id !== 'string' || answer.question_id.trim() === '') {
    errors.push(`answers[${index}].question_id e obrigatorio`);
  }
  if (!knownPrisms.has(answer.prisma)) {
    errors.push(`answers[${index}].prisma e invalido`);
  }
  const hasScore = typeof answer.score === 'number' && Number.isFinite(answer.score);
  const hasText = typeof answer.answer === 'string' && answer.answer.trim() !== '';
  if (!hasScore && !hasText) {
    errors.push(`answers[${index}] precisa de score numerico ou answer textual`);
  }
  if (hasScore && (answer.score < 0 || answer.score > 5)) {
    errors.push(`answers[${index}].score deve estar entre 0 e 5`);
  }
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      status: 'invalid_payload',
      request_id: payload.request_id ?? null,
      contract_version: 'beta-1',
      errors,
      metrics: {
        received_at: new Date(startedAtMs).toISOString(),
        n8n_processing_ms: Date.now() - startedAtMs,
      },
    },
  }];
}

return [{
  json: {
    valid: true,
    request: {
      contract_version: payload.contract_version,
      request_id: payload.request_id,
      form_response_id: payload.form_response_id,
      source: payload.source ?? 'unspecified',
      answers,
    },
    metrics: {
      received_at: new Date(startedAtMs).toISOString(),
      started_at_ms: startedAtMs,
    },
  },
}];

const data = $input.first().json;
const request = data.request;
const labels = {
  plasticidade_humana: 'Plasticidade humana',
  empreendedorismo: 'Empreendedorismo',
  multiculturalismo: 'Multiculturalismo',
  neuroinovacao: 'Neuroinovacao',
  tomada_decisao: 'Tomada de decisao',
};
const grouped = {};

for (const answer of request.answers) {
  grouped[answer.prisma] ??= { scores: [], textualAnswers: 0 };
  if (typeof answer.score === 'number') {
    grouped[answer.prisma].scores.push(answer.score);
  }
  if (typeof answer.answer === 'string' && answer.answer.trim() !== '') {
    grouped[answer.prisma].textualAnswers += 1;
  }
}

const prismScores = Object.entries(grouped).map(([prisma, values]) => {
  const average = values.scores.length === 0
    ? null
    : Number((values.scores.reduce((total, score) => total + score, 0) / values.scores.length).toFixed(2));
  return {
    prisma,
    label: labels[prisma],
    average_score: average,
    numeric_answers: values.scores.length,
    textual_answers: values.textualAnswers,
  };
});

const ranked = prismScores
  .filter((item) => item.average_score !== null)
  .sort((a, b) => b.average_score - a.average_score);
const strongest = ranked[0] ?? null;
const textualCount = prismScores.reduce((total, item) => total + item.textual_answers, 0);
const content = strongest
  ? `Na amostra beta, ${strongest.label} apresentou a maior media (${strongest.average_score}/5). Foram processadas ${request.answers.length} respostas, incluindo ${textualCount} resposta(s) textual(is).`
  : `A amostra beta processou ${request.answers.length} respostas textuais. Ainda nao ha notas numericas para comparar os prismas.`;
const finishedAtMs = Date.now();

return [{
  json: {
    status: 'completed',
    contract_version: request.contract_version,
    request_id: request.request_id,
    form_response_id: request.form_response_id,
    source: request.source,
    insight: {
      content,
      prism_scores: prismScores,
      evidence_summary: {
        answers_total: request.answers.length,
        numeric_answers: prismScores.reduce((total, item) => total + item.numeric_answers, 0),
        textual_answers: textualCount,
      },
      generator: 'deterministic-beta',
    },
    metrics: {
      received_at: data.metrics.received_at,
      finished_at: new Date(finishedAtMs).toISOString(),
      n8n_processing_ms: finishedAtMs - data.metrics.started_at_ms,
    },
  },
}];
